"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[8415],{49404:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[{"name":"Placement","desc":"A prefab the generator decided to place, resolved into an instance later by\\n`builder`.","fields":[{"name":"folder","lua_type":"string","desc":"Prefab folder under `ServerStorage.Prefab.maze`."},{"name":"name","lua_type":"string","desc":"Prefab model name within that folder."},{"name":"kind","lua_type":"\\"room\\" | \\"feature\\"","desc":"Which of the two generation passes produced this."},{"name":"cellX","lua_type":"number","desc":"Footprint origin column, chunk-local."},{"name":"cellY","lua_type":"number","desc":"Footprint origin row, chunk-local."},{"name":"xSpan","lua_type":"number","desc":"Footprint width in cells."},{"name":"ySpan","lua_type":"number","desc":"Footprint height in cells."},{"name":"rotation","lua_type":"number","desc":"Y rotation in radians."},{"name":"yOffset","lua_type":"number?","desc":"Extra vertical lift in studs, used to seat room floors."}],"source":{"line":32,"path":"src/common/shared/types/maze.luau"}},{"name":"MazeConfig","desc":"Streaming tuning. `viewDistanceCells` and `frameMs` are the inputs; the four\\nradii are derived by the `observers` system.\\n\\nThere is one budget, not one per stage. Independent slices summed to more\\nthan a frame and gave no stage priority over another; a single allowance\\nconsumed in phase order means teardown outranks building, and building\\noutranks warming caches, with no arithmetic to keep in sync.","fields":[{"name":"viewDistanceCells","lua_type":"number","desc":"Requested detail view distance in cells."},{"name":"detailRadius","lua_type":"number","desc":"Detail blocks kept loaded around an observer."},{"name":"detailDropRadius","lua_type":"number","desc":"Distance at which detail blocks are cached out."},{"name":"loadRadius","lua_type":"number","desc":"Chunks generated around an observer."},{"name":"unloadRadius","lua_type":"number","desc":"Distance at which chunks are destroyed."},{"name":"frameMs","lua_type":"number","desc":"Total milliseconds per frame the whole maze pipeline may spend."}],"source":{"line":62,"path":"src/common/shared/types/maze.luau"}}],"name":"mazeTypes","desc":"The plain record types the maze generation passes exchange.\\n\\nThese live outside `components` on purpose. Luau has no type-only import, so\\na module naming `components.Placement` requires `components` at runtime, and\\n`components` requires jecs \u2014 which is enough to stop a pure generation pass\\nfrom loading anywhere jecs is not present, including the test runner\'s backend.\\nDeclaring the records here keeps `rooms`, `features`, `generate` and `budget`\\nfree of that dependency; `components` re-exports them so existing references\\nkeep resolving.","tags":["common"],"source":{"line":15,"path":"src/common/shared/types/maze.luau"}}')}}]);